namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId;

    public NotificationService()
    {
        // Seed with initial fake data.
        Add("Welcome to the app!");
        Add("Your profile was updated.");
        Add("New feature: dark mode is available.");
    }

    public List<Notification> GetAll()
    {
        lock (_notifications)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_notifications)
        {
            return _notifications
                .Where(n => n.Id > lastSeenId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    private void Add(string message)
    {
        var id = Interlocked.Increment(ref _nextId);
        _notifications.Add(new Notification(id, message, DateTime.UtcNow));
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called by a hosted service so the polling page has something to find.
    /// </summary>
    public void GenerateFake()
    {
        string[] templates =
        [
            "Server health-check passed.",
            "Deployment completed successfully.",
            "A new user signed up.",
            "Disk usage alert cleared.",
            "Backup finished.",
            "Scheduled job ran without errors.",
        ];

        var msg = templates[Random.Shared.Next(templates.Length)];
        Add($"{msg} ({DateTime.UtcNow:T})");
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background service that periodically adds fake notifications so the
/// polling page has new data to discover.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.GenerateFake();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Runs during SSR *and* when the component re-initializes on the
    // interactive circuit.  We load the full list only on the first
    // (prerender) pass; see OnAfterRenderAsync for the hand-off.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _lastSeenId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
    }

    // Called only on the interactive (SignalR) render — never during SSR.
    // This is where we start the polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var newer = NotificationSvc.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _lastSeenId = newer.Max(n => n.Id);
                // Prepend new items so newest is on top.
                _notifications.InsertRange(0, newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

